import { createContext, ReactNode, useReducer } from "react";
// Начальное состояние
const initialState = { count: 0 };

interface ICounterContext {
  state: typeof initialState;
  dispatch: React.Dispatch<CounterReducerAction>;
}
// Создаем контекст
export const CounterContext = createContext<ICounterContext | null>(null);

type CounterReducerIncrementAction = {
  type: 'increment'
}
type CounterReducerDecrementAction = {
  type: 'decrement'
}
type CounterReducerAction = CounterReducerIncrementAction | CounterReducerDecrementAction


const useCounterContext = () => {
  const context = useContext(CounterContext);
  if (!context) {
    throw new Error('useCounterContext must be used within a CounterProvider');
  }
  return context;
}

// Редьюсер
const counterReducer = (state: typeof initialState, action: CounterReducerAction) => {
  const {type} = action
  switch (type) {
    case 'increment':
      return { count: state.count + 1 };
    case 'decrement':
      return { count: state.count - 1 };
    default:
      throw new Error(`Unknown action: ${type}`);
  }
};

// Поставщик контекста
export const CounterProvider = ({ children }: {children: ReactNode}) => {
  const [state, dispatch] = useReducer(counterReducer, initialState);

  return (
    <CounterContext.Provider value={{ state, dispatch }}>
      {children}
    </CounterContext.Provider>
  );
};
